INDEX_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <meta name=\"description\" content=\"Your personalized student dashboard for engineering news and college updates.\">\n    <meta name=\"theme-color\" content=\"#5145e5\">\n    <title>Student Ecosystem | Your Student Dashboard</title>\n    <link rel=\"stylesheet\" href=\"/style.css\">\n</head>\n<body>\n    <header class=\"site-header\">\n        <div class=\"container header-content\">\n            <a href=\"/\" class=\"brand\">\n                <span class=\"brand-icon\">SE</span>\n                <span><strong>Student Ecosystem</strong><small>Your campus. Your world.</small></span>\n            </a>\n            <nav class=\"main-nav\" aria-label=\"Main navigation\">\n                <a href=\"/\" class=\"nav-link active\">Dashboard</a>\n                <a href=\"/news\" class=\"nav-link\">Engineering News</a>\n                <a href=\"/college\" class=\"nav-link\">College Updates</a>\n            </nav>\n            <button class=\"theme-toggle\" id=\"theme-toggle\" type=\"button\" aria-label=\"Toggle colour theme\" aria-pressed=\"false\">\n                <span aria-hidden=\"true\">☾</span><span>Dark mode</span>\n            </button>\n        </div>\n    </header>\n\n    <main class=\"container dashboard\">\n        <section class=\"welcome-section\">\n            <div class=\"welcome-copy\">\n                <span class=\"eyebrow\">YOUR PERSONAL STUDENT HUB</span>\n                <h1>Stay curious.<br><span>Stay ahead.</span></h1>\n                <p>Discover engineering news, explore new opportunities, and keep up with important college updates—all in one place.</p>\n                <a href=\"#engineering-news\" class=\"button button-primary\">Explore today's news <span aria-hidden=\"true\">→</span></a>\n            </div>\n            <div class=\"welcome-card\">\n                <div class=\"welcome-card-top\"><span class=\"status-dot\"></span><span>YOUR DAILY BRIEFING</span></div>\n                <div class=\"welcome-illustration\" aria-hidden=\"true\">✦</div>\n                <h2>A smarter way to stay informed.</h2>\n                <p>Relevant updates, simplified with AI, so you can focus on what matters.</p>\n                <div class=\"welcome-card-footer\"><span>NEWS</span><span>·</span><span>LEARNING</span><span>·</span><span>CAMPUS</span></div>\n            </div>\n        </section>\n\n        <section class=\"quick-stats\" aria-label=\"Platform features\">\n            <article class=\"stat-card\"><span class=\"stat-icon\">◎</span><div><h3>Branch-focused</h3><p>News related to your field</p></div></article>\n            <article class=\"stat-card\"><span class=\"stat-icon\">✧</span><div><h3>AI summaries</h3><p>Understand news faster</p></div></article>\n            <article class=\"stat-card\"><span class=\"stat-icon\">▤</span><div><h3>Campus updates</h3><p>Notices, events and exams</p></div></article>\n        </section>\n\n        <section class=\"content-section\" id=\"engineering-news\">\n            <div class=\"section-heading\">\n                <div><span class=\"eyebrow\">CURATED FOR YOU</span><h2>Engineering news</h2><p>Discover what's happening in technology and engineering.</p></div>\n                <a href=\"/news\" class=\"text-link\">View all news <span aria-hidden=\"true\">→</span></a>\n            </div>\n            <div class=\"filter-panel\">\n                <div class=\"filter-field\">\n                    <label for=\"branch-select\">Your engineering branch</label>\n                    <select id=\"branch-select\">\n                        <option value=\"Artificial Intelligence\">Artificial Intelligence</option>\n                        <option value=\"Computer Science\">Computer Science</option>\n                        <option value=\"Electronics\">Electronics</option>\n                        <option value=\"Mechanical\">Mechanical</option>\n                        <option value=\"Civil\">Civil</option>\n                        <option value=\"Electrical\">Electrical</option>\n                    </select>\n                </div>\n                <button id=\"refresh-news\" class=\"button button-secondary\" type=\"button\"><span aria-hidden=\"true\">↻</span> Refresh news</button>\n            </div>\n            <div id=\"news-status\" class=\"status-message\" role=\"status\" aria-live=\"polite\">Choose your branch and load the latest news.</div>\n            <div id=\"news-count\" class=\"news-count\" aria-live=\"polite\"></div>\n            <div id=\"news-container\" class=\"news-grid\">\n                <article class=\"news-placeholder\"><div class=\"placeholder-icon\">✦</div><h3>Your daily briefing starts here</h3><p>Loading relevant engineering news will display articles and AI summaries here.</p></article>\n            </div>\n        </section>\n\n        <section class=\"content-section college-preview\">\n            <div class=\"section-heading\">\n                <div><span class=\"eyebrow\">YOUR CAMPUS, CONNECTED</span><h2>College updates</h2><p>Keep track of important notices, events and academic announcements.</p></div>\n                <a href=\"/college\" class=\"text-link\">Explore updates <span aria-hidden=\"true\">→</span></a>\n            </div>\n            <div class=\"college-preview-card\">\n                <div class=\"preview-icon\" aria-hidden=\"true\">⌂</div>\n                <div class=\"preview-copy\"><h3>Your college updates, in one place</h3><p>Official college updates will appear here once the college portal is configured.</p></div>\n                <a href=\"/college\" class=\"button button-secondary\">View college updates</a>\n            </div>\n        </section>\n\n        <section class=\"bottom-banner\">\n            <div><span class=\"eyebrow\">BUILT FOR ENGINEERING STUDENTS</span><h2>Less searching. More learning.</h2><p>Make your time as a student more informed, organized and productive.</p></div>\n            <span class=\"banner-symbol\" aria-hidden=\"true\">↗</span>\n        </section>\n    </main>\n\n    <footer class=\"site-footer\">\n        <div class=\"container footer-content\">\n            <a href=\"/\" class=\"footer-brand\">Student Ecosystem</a>\n            <p>Built to make student life a little smarter.</p>\n            <span>© <span id=\"current-year\">2026</span> Student Ecosystem</span>\n        </div>\n    </footer>\n    <script src=\"/script.js\" defer></script>\n</body>\n</html>\n"

STYLE_CSS = "/* =========================================\n   STUDENT ECOSYSTEM — GLOBAL DESIGN SYSTEM\n   ========================================= */\n\n:root {\n    --background: #f6f8fc;\n    --surface: #ffffff;\n    --surface-soft: #f0f4ff;\n    --primary: #4f46e5;\n    --primary-dark: #3730a3;\n    --primary-light: #e8eaff;\n    --text: #182230;\n    --text-secondary: #667085;\n    --border: #e5e9f2;\n    --success: #16a36a;\n    --shadow: 0 8px 30px rgba(25, 35, 70, 0.06);\n    --radius: 18px;\n    --container-width: 1160px;\n}\n\n* {\n    box-sizing: border-box;\n}\n\nhtml {\n    scroll-behavior: smooth;\n    scroll-padding-top: 90px;\n}\n\nbody {\n    margin: 0;\n    background: var(--background);\n    color: var(--text);\n    font-family: Inter, -apple-system, BlinkMacSystemFont, \"Segoe UI\",\n        Roboto, Arial, sans-serif;\n    font-size: 15px;\n    line-height: 1.65;\n    -webkit-font-smoothing: antialiased;\n}\n\na {\n    color: inherit;\n    text-decoration: none;\n}\n\nbutton,\nselect {\n    font: inherit;\n}\n\nbutton {\n    cursor: pointer;\n}\n\nbutton:focus-visible,\na:focus-visible,\nselect:focus-visible {\n    outline: 3px solid rgba(79, 70, 229, 0.35);\n    outline-offset: 3px;\n}\n\n.container {\n    width: min(var(--container-width), calc(100% - 48px));\n    margin-inline: auto;\n}\n\n/* =========================================\n   HEADER AND NAVIGATION\n   ========================================= */\n\n.site-header {\n    position: sticky;\n    top: 0;\n    z-index: 100;\n    background: rgba(255, 255, 255, 0.94);\n    border-bottom: 1px solid var(--border);\n    backdrop-filter: blur(14px);\n}\n\n.header-content {\n    min-height: 78px;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 28px;\n}\n\n.brand {\n    display: inline-flex;\n    align-items: center;\n    gap: 12px;\n    flex-shrink: 0;\n}\n\n.brand-icon {\n    width: 43px;\n    height: 43px;\n    display: grid;\n    place-items: center;\n    border-radius: 13px;\n    background: linear-gradient(135deg, #4f46e5, #7c3aed);\n    color: #ffffff;\n    font-size: 15px;\n    font-weight: 800;\n    letter-spacing: -0.5px;\n    box-shadow: 0 5px 14px rgba(79, 70, 229, 0.2);\n}\n\n.brand strong,\n.brand small {\n    display: block;\n}\n\n.brand strong {\n    font-size: 15px;\n    line-height: 1.5;\n    font-weight: 750;\n    letter-spacing: -0.35px;\n}\n\n.brand small {\n    color: var(--text-secondary);\n    font-size: 11px;\n    line-height: 1.5;\n}\n\n.main-nav {\n    display: flex;\n    align-items: center;\n    gap: 7px;\n}\n\n.nav-link {\n    padding: 9px 14px;\n    border-radius: 10px;\n    color: var(--text-secondary);\n    font-size: 13px;\n    font-weight: 600;\n    transition: color 0.2s ease, background 0.2s ease;\n}\n\n.nav-link:hover {\n    color: var(--primary);\n    background: var(--surface-soft);\n}\n\n.nav-link.active {\n    color: var(--primary);\n    background: var(--primary-light);\n}\n\n/* =========================================\n   BUTTONS AND LINKS\n   ========================================= */\n\n.button {\n    min-height: 44px;\n    display: inline-flex;\n    justify-content: center;\n    align-items: center;\n    gap: 9px;\n    padding: 10px 17px;\n    border: 1px solid transparent;\n    border-radius: 11px;\n    font-size: 13px;\n    font-weight: 700;\n    transition: transform 0.2s ease, background 0.2s ease,\n        box-shadow 0.2s ease;\n}\n\n.button:hover {\n    transform: translateY(-1px);\n}\n\n.button-primary {\n    background: var(--primary);\n    color: #ffffff;\n    box-shadow: 0 5px 13px rgba(79, 70, 229, 0.16);\n}\n\n.button-primary:hover {\n    background: var(--primary-dark);\n    box-shadow: 0 7px 18px rgba(79, 70, 229, 0.23);\n}\n\n.button-secondary {\n    background: var(--surface);\n    border-color: var(--border);\n    color: var(--text);\n}\n\n.button-secondary:hover {\n    border-color: #c7c9ff;\n    background: var(--surface-soft);\n}\n\n.button:disabled {\n    opacity: 0.6;\n    cursor: not-allowed;\n    transform: none;\n}\n\n.text-link {\n    display: inline-flex;\n    align-items: center;\n    gap: 7px;\n    color: var(--primary);\n    font-size: 13px;\n    font-weight: 700;\n    white-space: nowrap;\n}\n\n.text-link:hover {\n    color: var(--primary-dark);\n}\n\n.back-link {\n    display: inline-flex;\n    margin-top: 32px;\n    color: var(--primary);\n    font-size: 13px;\n    font-weight: 700;\n}\n\n.back-link:hover {\n    color: var(--primary-dark);\n}\n\n/* =========================================\n   EYEBROWS AND SECTION HEADINGS\n   ========================================= */\n\n.eyebrow {\n    display: inline-block;\n    color: var(--primary);\n    font-size: 10px;\n    font-weight: 800;\n    letter-spacing: 1.6px;\n    line-height: 1.7;\n}\n\n.section-heading {\n    display: flex;\n    align-items: flex-end;\n    justify-content: space-between;\n    gap: 20px;\n    margin-bottom: 23px;\n}\n\n.section-heading h2 {\n    margin: 5px 0 4px;\n    font-size: clamp(23px, 3vw, 29px);\n    line-height: 1.3;\n    letter-spacing: -1px;\n}\n\n.section-heading p {\n    margin: 0;\n    color: var(--text-secondary);\n    font-size: 13px;\n}\n\n/* =========================================\n   DASHBOARD HERO\n   ========================================= */\n\n.dashboard {\n    padding-top: 36px;\n    padding-bottom: 64px;\n}\n\n.welcome-section {\n    display: grid;\n    grid-template-columns: 1.1fr 0.9fr;\n    align-items: center;\n    gap: 42px;\n    padding: 42px 0 36px;\n}\n\n.welcome-copy h1 {\n    margin: 13px 0 17px;\n    font-size: clamp(38px, 5vw, 58px);\n    line-height: 1.1;\n    letter-spacing: -2.8px;\n    font-weight: 800;\n}\n\n.welcome-copy h1 span,\n.page-hero h1 span {\n    color: var(--primary);\n}\n\n.welcome-copy > p {\n    max-width: 510px;\n    margin: 0 0 25px;\n    color: var(--text-secondary);\n    font-size: 15px;\n    line-height: 1.9;\n}\n\n.welcome-card {\n    position: relative;\n    overflow: hidden;\n    min-height: 300px;\n    padding: 27px;\n    border: 1px solid #e5e4ff;\n    border-radius: 24px;\n    background:\n        radial-gradient(circle at 85% 10%, rgba(183, 173, 255, 0.38), transparent 35%),\n        linear-gradient(145deg, #ffffff, #f0efff);\n    box-shadow: var(--shadow);\n}\n\n.welcome-card-top {\n    display: flex;\n    align-items: center;\n    gap: 9px;\n    color: var(--text-secondary);\n    font-size: 10px;\n    font-weight: 800;\n    letter-spacing: 1.2px;\n}\n\n.status-dot {\n    width: 8px;\n    height: 8px;\n    border-radius: 50%;\n    background: var(--success);\n    box-shadow: 0 0 0 4px rgba(22, 163, 106, 0.1);\n}\n\n.welcome-illustration {\n    width: 72px;\n    height: 72px;\n    display: grid;\n    place-items: center;\n    margin: 25px 0 16px;\n    border: 1px solid rgba(79, 70, 229, 0.1);\n    border-radius: 22px;\n    background: rgba(255, 255, 255, 0.85);\n    color: var(--primary);\n    font-size: 42px;\n    box-shadow: 0 8px 22px rgba(79, 70, 229, 0.08);\n}\n\n.welcome-card h2 {\n    max-width: 330px;\n    margin: 0 0 9px;\n    font-size: 23px;\n    line-height: 1.4;\n    letter-spacing: -0.7px;\n}\n\n.welcome-card > p {\n    max-width: 360px;\n    margin: 0;\n    color: var(--text-secondary);\n    font-size: 13px;\n}\n\n.welcome-card-footer {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 10px;\n    margin-top: 22px;\n    color: #7776a3;\n    font-size: 9px;\n    font-weight: 800;\n    letter-spacing: 1px;\n}\n\n/* =========================================\n   QUICK STATS\n   ========================================= */\n\n.quick-stats {\n    display: grid;\n    grid-template-columns: repeat(3, minmax(0, 1fr));\n    gap: 17px;\n    margin: 7px 0 62px;\n}\n\n.stat-card {\n    display: flex;\n    align-items: center;\n    gap: 15px;\n    padding: 21px;\n    border: 1px solid var(--border);\n    border-radius: 16px;\n    background: var(--surface);\n    box-shadow: 0 4px 16px rgba(25, 35, 70, 0.025);\n}\n\n.stat-icon {\n    width: 43px;\n    height: 43px;\n    display: grid;\n    flex-shrink: 0;\n    place-items: center;\n    border-radius: 13px;\n    background: var(--primary-light);\n    color: var(--primary);\n    font-size: 23px;\n}\n\n.stat-card h3 {\n    margin: 0 0 2px;\n    font-size: 13px;\n    font-weight: 750;\n}\n\n.stat-card p {\n    margin: 0;\n    color: var(--text-secondary);\n    font-size: 11px;\n}\n\n/* =========================================\n   GENERAL CONTENT SECTIONS\n   ========================================= */\n\n.content-section {\n    margin-top: 54px;\n}\n\n.filter-panel,\n.news-controls {\n    display: flex;\n    align-items: flex-end;\n    justify-content: space-between;\n    gap: 18px;\n    margin: 24px 0;\n    padding: 21px;\n    border: 1px solid var(--border);\n    border-radius: 16px;\n    background: var(--surface);\n}\n\n.filter-field {\n    display: flex;\n    flex-direction: column;\n    gap: 7px;\n    width: min(100%, 360px);\n}\n\n.filter-field label,\n.college-filter label {\n    color: var(--text);\n    font-size: 12px;\n    font-weight: 700;\n}\n\nselect {\n    width: 100%;\n    min-height: 45px;\n    padding: 10px 37px 10px 13px;\n    border: 1px solid #dfe3ed;\n    border-radius: 10px;\n    background-color: #ffffff;\n    color: var(--text);\n    font-size: 13px;\n    outline: none;\n}\n\nselect:focus {\n    border-color: var(--primary);\n}\n\n.status-message {\n    margin: 15px 0;\n    color: var(--text-secondary);\n    font-size: 13px;\n}\n\n.status-message:empty {\n    display: none;\n}\n\n/* =========================================\n   NEWS GRID AND NEWS CARDS\n   ========================================= */\n\n.news-grid {\n    display: grid;\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n    gap: 20px;\n}\n\n.news-card {\n    min-width: 0;\n    padding: 23px;\n    border: 1px solid var(--border);\n    border-radius: var(--radius);\n    background: var(--surface);\n    box-shadow: 0 4px 18px rgba(25, 35, 70, 0.025);\n    transition: transform 0.2s ease, box-shadow 0.2s ease,\n        border-color 0.2s ease;\n}\n\n.news-card:hover {\n    transform: translateY(-3px);\n    border-color: #d8d9ff;\n    box-shadow: var(--shadow);\n}\n\n.news-card-meta {\n    display: flex;\n    flex-wrap: wrap;\n    align-items: center;\n    gap: 9px;\n    margin-bottom: 13px;\n    color: var(--text-secondary);\n    font-size: 10px;\n}\n\n.news-source {\n    padding: 4px 8px;\n    border-radius: 6px;\n    background: var(--primary-light);\n    color: var(--primary-dark);\n    font-weight: 750;\n}\n\n.news-card h3 {\n    margin: 0 0 12px;\n    font-size: 17px;\n    line-height: 1.5;\n    letter-spacing: -0.35px;\n    overflow-wrap: anywhere;\n}\n\n.news-card h3 a:hover {\n    color: var(--primary);\n}\n\n.news-description {\n    margin: 0 0 16px;\n    color: var(--text-secondary);\n    font-size: 12px;\n    line-height: 1.8;\n}\n\n.summary-box {\n    margin-top: 17px;\n    padding: 16px;\n    border: 1px solid #e7e7ff;\n    border-radius: 12px;\n    background: #f8f8ff;\n}\n\n.summary-label {\n    display: flex;\n    align-items: center;\n    gap: 7px;\n    margin-bottom: 10px;\n    color: var(--primary-dark);\n    font-size: 10px;\n    font-weight: 800;\n    letter-spacing: 0.9px;\n    text-transform: uppercase;\n}\n\n.summary-box ul {\n    margin: 0;\n    padding-left: 17px;\n    color: #485168;\n    font-size: 12px;\n    line-height: 1.8;\n}\n\n.summary-box li + li {\n    margin-top: 6px;\n}\n\n.news-card-footer {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    gap: 12px;\n    margin-top: 18px;\n    padding-top: 14px;\n    border-top: 1px solid #edf0f6;\n}\n\n.article-date {\n    color: var(--text-secondary);\n    font-size: 10px;\n}\n\n.article-link {\n    color: var(--primary);\n    font-size: 11px;\n    font-weight: 750;\n}\n\n.article-link:hover {\n    color: var(--primary-dark);\n}\n\n/* =========================================\n   PLACEHOLDERS AND EMPTY STATES\n   ========================================= */\n\n.news-placeholder {\n    grid-column: 1 / -1;\n    padding: 42px 25px;\n    border: 1px dashed #d7dbee;\n    border-radius: var(--radius);\n    background: rgba(255, 255, 255, 0.75);\n    text-align: center;\n}\n\n.placeholder-icon {\n    width: 54px;\n    height: 54px;\n    display: grid;\n    place-items: center;\n    margin: 0 auto 15px;\n    border-radius: 16px;\n    background: var(--primary-light);\n    color: var(--primary);\n    font-size: 28px;\n}\n\n.news-placeholder h3 {\n    margin: 0 0 7px;\n    font-size: 17px;\n}\n\n.news-placeholder p {\n    max-width: 470px;\n    margin: 0 auto;\n    color: var(--text-secondary);\n    font-size: 13px;\n}\n\n/* =========================================\n   COLLEGE PAGE\n   ========================================= */\n\n.page-content {\n    padding-top: 40px;\n    padding-bottom: 65px;\n}\n\n.page-hero {\n    padding: 28px 0 31px;\n}\n\n.page-hero h1 {\n    margin: 12px 0;\n    font-size: clamp(36px, 5vw, 53px);\n    line-height: 1.18;\n    letter-spacing: -2.2px;\n}\n\n.page-hero > p {\n    max-width: 690px;\n    margin: 0;\n    color: var(--text-secondary);\n    font-size: 15px;\n    line-height: 1.9;\n}\n\n.college-overview {\n    display: grid;\n    grid-template-columns: repeat(3, minmax(0, 1fr));\n    gap: 17px;\n    margin: 15px 0 55px;\n}\n\n.overview-card {\n    padding: 23px;\n    border: 1px solid var(--border);\n    border-radius: 16px;\n    background: var(--surface);\n}\n\n.overview-icon {\n    width: 44px;\n    height: 44px;\n    display: grid;\n    place-items: center;\n    margin-bottom: 15px;\n    border-radius: 13px;\n    background: var(--primary-light);\n    color: var(--primary);\n    font-size: 23px;\n}\n\n.overview-card h3 {\n    margin: 0 0 6px;\n    font-size: 14px;\n}\n\n.overview-card p {\n    margin: 0;\n    color: var(--text-secondary);\n    font-size: 12px;\n    line-height: 1.8;\n}\n\n.college-filter {\n    display: flex;\n    align-items: center;\n    gap: 15px;\n    margin: 20px 0;\n}\n\n.college-filter select {\n    width: min(100%, 260px);\n}\n\n.college-updates-list {\n    display: grid;\n    gap: 15px;\n}\n\n.college-update-card {\n    display: flex;\n    align-items: flex-start;\n    gap: 16px;\n    padding: 21px;\n    border: 1px solid var(--border);\n    border-radius: 15px;\n    background: var(--surface);\n    transition: border-color 0.2s ease, box-shadow 0.2s ease;\n}\n\n.college-update-card:hover {\n    border-color: #d8d9ff;\n    box-shadow: var(--shadow);\n}\n\n.update-icon {\n    width: 43px;\n    height: 43px;\n    display: grid;\n    flex-shrink: 0;\n    place-items: center;\n    border-radius: 12px;\n    background: var(--primary-light);\n    color: var(--primary);\n    font-size: 21px;\n}\n\n.update-content {\n    flex: 1;\n    min-width: 0;\n}\n\n.update-content h3 {\n    margin: 0 0 7px;\n    font-size: 15px;\n    line-height: 1.5;\n    overflow-wrap: anywhere;\n}\n\n.update-content p {\n    margin: 0 0 9px;\n    color: var(--text-secondary);\n    font-size: 12px;\n}\n\n.update-meta {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 9px;\n    align-items: center;\n    color: var(--text-secondary);\n    font-size: 10px;\n}\n\n.update-category {\n    padding: 3px 8px;\n    border-radius: 6px;\n    background: #eef2ff;\n    color: #4338ca;\n    font-weight: 750;\n}\n\n.update-link {\n    display: inline-block;\n    margin-top: 11px;\n    color: var(--primary);\n    font-size: 12px;\n    font-weight: 750;\n}\n\n.official-source-note {\n    display: flex;\n    gap: 15px;\n    margin-top: 35px;\n    padding: 22px;\n    border: 1px solid #dfe4ff;\n    border-radius: 15px;\n    background: #f0f2ff;\n}\n\n.source-note-icon {\n    color: var(--primary);\n    font-size: 24px;\n    line-height: 1.3;\n}\n\n.official-source-note h3 {\n    margin: 0 0 5px;\n    font-size: 13px;\n}\n\n.official-source-note p {\n    margin: 0;\n    color: var(--text-secondary);\n    font-size: 12px;\n    line-height: 1.8;\n}\n\n/* =========================================\n   DASHBOARD COLLEGE PREVIEW\n   ========================================= */\n\n.college-preview-card {\n    display: flex;\n    align-items: center;\n    gap: 17px;\n    padding: 23px;\n    border: 1px solid var(--border);\n    border-radius: 16px;\n    background: var(--surface);\n}\n\n.preview-icon {\n    width: 52px;\n    height: 52px;\n    display: grid;\n    flex-shrink: 0;\n    place-items: center;\n    border-radius: 15px;\n    background: var(--primary-light);\n    color: var(--primary);\n    font-size: 28px;\n}\n\n.preview-copy {\n    flex: 1;\n}\n\n.preview-copy h3 {\n    margin: 0 0 5px;\n    font-size: 14px;\n}\n\n.preview-copy p {\n    margin: 0;\n    color: var(--text-secondary);\n    font-size: 12px;\n}\n\n/* =========================================\n   BOTTOM BANNER\n   ========================================= */\n\n.bottom-banner {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 20px;\n    margin-top: 58px;\n    padding: 30px;\n    border: 1px solid #e3e2ff;\n    border-radius: 20px;\n    background: linear-gradient(120deg, #f0efff, #ffffff);\n}\n\n.bottom-banner h2 {\n    margin: 7px 0;\n    font-size: 23px;\n    letter-spacing: -0.7px;\n}\n\n.bottom-banner p {\n    margin: 0;\n    color: var(--text-secondary);\n    font-size: 13px;\n}\n\n.banner-symbol {\n    width: 58px;\n    height: 58px;\n    display: grid;\n    flex-shrink: 0;\n    place-items: center;\n    border-radius: 18px;\n    background: var(--primary);\n    color: #ffffff;\n    font-size: 30px;\n}\n\n/* =========================================\n   NEWS PAGE ADDITIONS\n   ========================================= */\n\n.result-badge {\n    padding: 7px 11px;\n    border: 1px solid var(--border);\n    border-radius: 9px;\n    background: var(--surface);\n    color: var(--text-secondary);\n    font-size: 11px;\n    font-weight: 700;\n    white-space: nowrap;\n}\n\n.ai-explainer {\n    display: flex;\n    align-items: flex-start;\n    gap: 19px;\n    margin-top: 45px;\n    padding: 25px;\n    border: 1px solid #e4e2ff;\n    border-radius: 18px;\n    background: linear-gradient(120deg, #f0efff, #ffffff);\n}\n\n.ai-explainer-icon {\n    width: 48px;\n    height: 48px;\n    display: grid;\n    flex-shrink: 0;\n    place-items: center;\n    border-radius: 14px;\n    background: #ffffff;\n    color: var(--primary);\n    font-size: 29px;\n}\n\n.ai-explainer h2 {\n    margin: 5px 0 7px;\n    font-size: 20px;\n    letter-spacing: -0.5px;\n}\n\n.ai-explainer p {\n    margin: 0;\n    color: var(--text-secondary);\n    font-size: 13px;\n    line-height: 1.9;\n}\n\n/* =========================================\n   FOOTER\n   ========================================= */\n\n.site-footer {\n    border-top: 1px solid var(--border);\n    background: #ffffff;\n}\n\n.footer-content {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 20px;\n    min-height: 84px;\n    padding-top: 15px;\n    padding-bottom: 15px;\n}\n\n.footer-brand {\n    font-size: 13px;\n    font-weight: 800;\n}\n\n.footer-content p,\n.footer-content > span {\n    margin: 0;\n    color: var(--text-secondary);\n    font-size: 11px;\n}\n\n/* =========================================\n   LOADING AND ERROR STATES\n   ========================================= */\n\n.loading-indicator {\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    gap: 11px;\n    padding: 38px 20px;\n    color: var(--text-secondary);\n    font-size: 13px;\n}\n\n.loading-spinner {\n    width: 19px;\n    height: 19px;\n    border: 2px solid #e0e3f3;\n    border-top-color: var(--primary);\n    border-radius: 50%;\n    animation: spin 0.8s linear infinite;\n}\n\n@keyframes spin {\n    to {\n        transform: rotate(360deg);\n    }\n}\n\n/* Respect users who prefer less animation. */\n@media (prefers-reduced-motion: reduce) {\n    *,\n    *::before,\n    *::after {\n        scroll-behavior: auto !important;\n        animation-duration: 0.01ms !important;\n        animation-iteration-count: 1 !important;\n        transition-duration: 0.01ms !important;\n    }\n}\n\n/* =========================================\n   TABLET RESPONSIVENESS\n   ========================================= */\n\n@media (max-width: 900px) {\n    .welcome-section {\n        grid-template-columns: 1fr 0.9fr;\n        gap: 25px;\n    }\n\n    .welcome-copy h1 {\n        font-size: 43px;\n    }\n\n    .quick-stats {\n        gap: 11px;\n    }\n\n    .stat-card {\n        padding: 15px;\n        gap: 10px;\n    }\n\n    .news-grid {\n        grid-template-columns: 1fr;\n    }\n\n    .college-overview {\n        gap: 12px;\n    }\n\n    .overview-card {\n        padding: 17px;\n    }\n}\n\n/* =========================================\n   MOBILE RESPONSIVENESS\n   ========================================= */\n\n@media (max-width: 650px) {\n    .container {\n        width: calc(100% - 30px);\n    }\n\n    .header-content {\n        align-items: flex-start;\n        flex-direction: column;\n        gap: 12px;\n        padding-top: 13px;\n        padding-bottom: 12px;\n    }\n\n    .brand-icon {\n        width: 39px;\n        height: 39px;\n    }\n\n    .main-nav {\n        width: 100%;\n        gap: 4px;\n        overflow-x: auto;\n        padding-bottom: 2px;\n    }\n\n    .nav-link {\n        padding: 8px 10px;\n        font-size: 11px;\n        white-space: nowrap;\n    }\n\n    .dashboard {\n        padding-top: 17px;\n    }\n\n    .welcome-section {\n        grid-template-columns: 1fr;\n        gap: 27px;\n        padding: 27px 0;\n    }\n\n    .welcome-copy h1 {\n        font-size: 43px;\n        letter-spacing: -2px;\n    }\n\n    .welcome-copy > p {\n        font-size: 13px;\n    }\n\n    .welcome-card {\n        min-height: auto;\n        padding: 22px;\n    }\n\n    .quick-stats {\n        grid-template-columns: 1fr;\n        gap: 10px;\n        margin-bottom: 45px;\n    }\n\n    .stat-card {\n        padding: 16px;\n    }\n\n    .content-section {\n        margin-top: 43px;\n    }\n\n    .section-heading {\n        align-items: flex-start;\n        flex-direction: column;\n        gap: 12px;\n    }\n\n    .section-heading h2 {\n        font-size: 25px;\n    }\n\n    .filter-panel,\n    .news-controls {\n        align-items: stretch;\n        flex-direction: column;\n        padding: 16px;\n    }\n\n    .filter-field {\n        width: 100%;\n    }\n\n    .news-controls .button,\n    .filter-panel .button {\n        width: 100%;\n    }\n\n    .news-card {\n        padding: 18px;\n    }\n\n    .page-content {\n        padding-top: 23px;\n    }\n\n    .page-hero {\n        padding-top: 20px;\n    }\n\n    .page-hero h1 {\n        font-size: 39px;\n        letter-spacing: -1.8px;\n    }\n\n    .page-hero > p {\n        font-size: 13px;\n    }\n\n    .college-overview {\n        grid-template-columns: 1fr;\n        gap: 11px;\n        margin-bottom: 42px;\n    }\n\n    .overview-card {\n        padding: 18px;\n    }\n\n    .overview-icon {\n        margin-bottom: 10px;\n    }\n\n    .college-filter {\n        align-items: stretch;\n        flex-direction: column;\n        gap: 7px;\n    }\n\n    .college-filter select {\n        width: 100%;\n    }\n\n    .college-update-card {\n        padding: 16px;\n        gap: 11px;\n    }\n\n    .update-icon {\n        width: 37px;\n        height: 37px;\n    }\n\n    .college-preview-card {\n        align-items: flex-start;\n        flex-direction: column;\n        padding: 18px;\n    }\n\n    .college-preview-card .button {\n        width: 100%;\n    }\n\n    .bottom-banner {\n        padding: 22px;\n    }\n\n    .bottom-banner h2 {\n        font-size: 20px;\n    }\n\n    .banner-symbol {\n        width: 43px;\n        height: 43px;\n        border-radius: 13px;\n        font-size: 23px;\n    }\n\n    .ai-explainer {\n        padding: 19px;\n        gap: 12px;\n    }\n\n    .ai-explainer-icon {\n        width: 39px;\n        height: 39px;\n    }\n\n    .footer-content {\n        align-items: flex-start;\n        flex-direction: column;\n        justify-content: center;\n        gap: 5px;\n        padding-top: 18px;\n        padding-bottom: 18px;\n    }\n}\n\n@media (max-width: 380px) {\n    .welcome-copy h1 {\n        font-size: 37px;\n    }\n\n    .page-hero h1 {\n        font-size: 34px;\n    }\n\n    .bottom-banner {\n        align-items: flex-start;\n    }\n\n    .banner-symbol {\n        display: none;\n    }\n}\n\n/* ===== VIBRANT BLUE / PURPLE REFRESH ===== */\n:root {\n    --background: #f4f6ff;\n    --surface: #ffffff;\n    --surface-soft: #eef0ff;\n    --primary: #5145e5;\n    --primary-dark: #392db8;\n    --primary-light: #e9e7ff;\n    --accent-blue: #2998ff;\n    --accent-purple: #8b5cf6;\n    --text: #172033;\n    --text-secondary: #65708a;\n    --border: #e1e5f3;\n    --shadow: 0 14px 38px rgba(65, 57, 160, .10);\n}\n\nbody {\n    background:\n      radial-gradient(ellipse at 8% 0%, rgba(89, 104, 255, .10), transparent 34rem),\n      radial-gradient(ellipse at 92% 18%, rgba(168, 85, 247, .09), transparent 30rem),\n      var(--background);\n    transition: background .25s ease, color .25s ease;\n}\n.site-header {\n    background: rgba(255,255,255,.82);\n    backdrop-filter: blur(18px);\n    border-bottom: 1px solid var(--border);\n}\n.brand-icon {\n    background: linear-gradient(135deg, #397bff, #7546e8 70%, #a855f7);\n    box-shadow: 0 7px 18px rgba(91, 76, 220, .28);\n}\n.nav-link { transition: color .2s ease, background .2s ease, transform .2s ease; }\n.nav-link:hover { transform: translateY(-2px); }\n.button-primary, .button-secondary {\n    transition: transform .2s ease, box-shadow .2s ease, filter .2s ease;\n}\n.button-primary {\n    background: linear-gradient(120deg, #367df7, #6248e8 58%, #914de8);\n    box-shadow: 0 9px 22px rgba(83, 79, 220, .24);\n}\n.button-primary:hover, .button-secondary:hover {\n    transform: translateY(-2px);\n    box-shadow: 0 12px 25px rgba(83, 79, 220, .20);\n}\n.welcome-card {\n    background: linear-gradient(140deg, #273fbd, #6044d9 55%, #9b4de5);\n    box-shadow: 0 22px 50px rgba(76, 64, 190, .24);\n}\n.stat-card, .news-card, .college-preview-card, .filter-panel {\n    border: 1px solid var(--border);\n    box-shadow: var(--shadow);\n    transition: transform .22s ease, box-shadow .22s ease, background .22s ease;\n}\n.stat-card:hover, .news-card:hover, .college-preview-card:hover {\n    transform: translateY(-5px);\n    box-shadow: 0 18px 42px rgba(65, 57, 160, .15);\n}\n.eyebrow, .text-link { color: var(--primary); }\n.summary-box {\n    border-color: rgba(111, 86, 235, .22);\n    background: linear-gradient(135deg, rgba(83, 112, 255, .08), rgba(168, 85, 247, .09));\n}\n.bottom-banner {\n    background: linear-gradient(115deg, #263db6, #5845d4 58%, #8748db);\n    box-shadow: 0 18px 40px rgba(71, 61, 174, .20);\n}\n.theme-toggle {\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    gap: 8px;\n    min-height: 40px;\n    padding: 8px 13px;\n    border: 1px solid var(--border);\n    border-radius: 12px;\n    background: var(--surface);\n    color: var(--text);\n    font: inherit;\n    font-size: 13px;\n    font-weight: 700;\n    cursor: pointer;\n}\n.theme-toggle:hover { border-color: var(--primary); color: var(--primary); }\n\n/* Dark theme is controlled by data-theme on <html>. */\nhtml[data-theme=\"dark\"] {\n    color-scheme: dark;\n    --background: #0b1020;\n    --surface: #121a2e;\n    --surface-soft: #192440;\n    --primary: #9b8cff;\n    --primary-dark: #b5aaff;\n    --primary-light: #29234c;\n    --text: #f1f3ff;\n    --text-secondary: #aab5d0;\n    --border: rgba(172, 181, 224, .15);\n    --shadow: 0 14px 38px rgba(0, 0, 0, .24);\n}\nhtml[data-theme=\"dark\"] body {\n    background:\n      radial-gradient(ellipse at 8% 0%, rgba(75, 91, 220, .18), transparent 34rem),\n      radial-gradient(ellipse at 92% 18%, rgba(139, 92, 246, .15), transparent 30rem),\n      var(--background);\n}\nhtml[data-theme=\"dark\"] .site-header {\n    background: rgba(13, 19, 37, .86);\n}\nhtml[data-theme=\"dark\"] .stat-card,\nhtml[data-theme=\"dark\"] .news-card,\nhtml[data-theme=\"dark\"] .college-preview-card,\nhtml[data-theme=\"dark\"] .filter-panel,\nhtml[data-theme=\"dark\"] .theme-toggle {\n    background: var(--surface);\n    color: var(--text);\n    border-color: var(--border);\n}\nhtml[data-theme=\"dark\"] select,\nhtml[data-theme=\"dark\"] input {\n    background: #18233d;\n    color: var(--text);\n    border-color: var(--border);\n}\nhtml[data-theme=\"dark\"] .news-placeholder,\nhtml[data-theme=\"dark\"] .loading-indicator {\n    background: var(--surface);\n    color: var(--text);\n}\nhtml[data-theme=\"dark\"] .news-description,\nhtml[data-theme=\"dark\"] .stat-card p,\nhtml[data-theme=\"dark\"] .section-heading p,\nhtml[data-theme=\"dark\"] .preview-copy p {\n    color: var(--text-secondary);\n}\nhtml[data-theme=\"dark\"] .site-footer {\n    background: #090e1b;\n    border-color: var(--border);\n}\nhtml[data-theme=\"dark\"] .summary-box {\n    background: rgba(124, 92, 255, .13);\n}\n@media (prefers-reduced-motion: reduce) {\n    *, *::before, *::after {\n        scroll-behavior: auto !important;\n        animation-duration: .01ms !important;\n        transition-duration: .01ms !important;\n    }\n}\n"

SCRIPT_JS = "\"use strict\";\n\n/* =========================================\n   STUDENT ECOSYSTEM — FRONTEND CONTROLLER\n   ========================================= */\n\nconst API = {\n    news: \"/api/news\",\n    college: \"/api/college-updates\"\n};\n\ndocument.addEventListener(\"DOMContentLoaded\", () => {\n    updateCurrentYear();\n    initializeTheme();\n    initializeNews();\n    initializeCollegeUpdates();\n});\n\n/* =========================================\n   GENERAL HELPERS\n   ========================================= */\n\nfunction updateCurrentYear() {\n    const yearElement = document.getElementById(\"current-year\");\n\n    if (yearElement) {\n        yearElement.textContent = new Date().getFullYear();\n    }\n}\n\nfunction createElement(tag, className, text) {\n    const element = document.createElement(tag);\n\n    if (className) {\n        element.className = className;\n    }\n\n    if (text !== undefined && text !== null) {\n        element.textContent = String(text);\n    }\n\n    return element;\n}\n\nfunction setStatus(element, message, isError = false) {\n    if (!element) return;\n\n    element.textContent = message;\n    element.classList.toggle(\"status-error\", isError);\n}\n\nfunction showLoading(container, message) {\n    if (!container) return;\n\n    container.replaceChildren();\n\n    const loading = createElement(\"div\", \"loading-indicator\");\n    const spinner = createElement(\"span\", \"loading-spinner\");\n\n    spinner.setAttribute(\"aria-hidden\", \"true\");\n\n    loading.append(\n        spinner,\n        createElement(\"span\", \"\", message)\n    );\n\n    container.appendChild(loading);\n}\n\nfunction showEmptyState(container, title, message) {\n    if (!container) return;\n\n    const card = createElement(\"article\", \"news-placeholder\");\n    const icon = createElement(\"div\", \"placeholder-icon\", \"✦\");\n\n    icon.setAttribute(\"aria-hidden\", \"true\");\n\n    card.append(\n        icon,\n        createElement(\"h3\", \"\", title),\n        createElement(\"p\", \"\", message)\n    );\n\n    container.replaceChildren(card);\n}\n\nasync function fetchJSON(url) {\n    const response = await fetch(url, {\n        headers: {\n            Accept: \"application/json\"\n        }\n    });\n\n    let data;\n\n    try {\n        data = await response.json();\n    } catch {\n        throw new Error(\"The server returned an invalid response.\");\n    }\n\n    if (!response.ok) {\n        throw new Error(\n            data.error || `Request failed with status ${response.status}.`\n        );\n    }\n\n    return data;\n}\n\nfunction formatDate(value) {\n    if (!value) return \"Date unavailable\";\n\n    const date = new Date(value);\n\n    if (Number.isNaN(date.getTime())) {\n        return \"Date unavailable\";\n    }\n\n    return new Intl.DateTimeFormat(\"en-IN\", {\n        day: \"numeric\",\n        month: \"short\",\n        year: \"numeric\"\n    }).format(date);\n}\n\nfunction createSafeExternalLink(url, label, className = \"\") {\n    const link = createElement(\"a\", className, label);\n\n    try {\n        const parsedURL = new URL(url);\n\n        if (![\"http:\", \"https:\"].includes(parsedURL.protocol)) {\n            return null;\n        }\n\n        link.href = parsedURL.href;\n        link.target = \"_blank\";\n        link.rel = \"noopener noreferrer\";\n\n        return link;\n    } catch {\n        return null;\n    }\n}\n\n/* =========================================\n   ENGINEERING NEWS\n   ========================================= */\n\nfunction initializeNews() {\n    const branchSelect = document.getElementById(\"branch-select\");\n    const refreshButton = document.getElementById(\"refresh-news\");\n    const newsContainer = document.getElementById(\"news-container\");\n    const newsStatus = document.getElementById(\"news-status\");\n\n    if (!branchSelect || !refreshButton || !newsContainer) {\n        return;\n    }\n\n    const savedBranch = localStorage.getItem(\"student-ecosystem-branch\");\n\n    if (\n        savedBranch &&\n        Array.from(branchSelect.options).some(\n            option => option.value === savedBranch\n        )\n    ) {\n        branchSelect.value = savedBranch;\n    }\n\n    async function loadNews(forceRefresh = false) {\n        const branch = branchSelect.value;\n\n        localStorage.setItem(\"student-ecosystem-branch\", branch);\n\n        const params = new URLSearchParams({\n            branch,\n            limit: \"8\"\n        });\n\n        if (forceRefresh) {\n            params.set(\"refresh\", \"true\");\n        }\n\n        refreshButton.disabled = true;\n        refreshButton.textContent = forceRefresh\n            ? \"Refreshing…\"\n            : \"Loading news…\";\n\n        setStatus(newsStatus, \"Finding engineering news for your branch…\");\n        showLoading(newsContainer, \"Loading articles and preparing AI summaries…\");\n\n        try {\n            const data = await fetchJSON(`${API.news}?${params.toString()}`);\n\n            renderNews(newsContainer, data.articles || []);\n\n            const count = Number(data.count ?? (data.articles || []).length);\n            const countElement = document.getElementById(\"news-count\");\n\n            if (countElement) {\n                countElement.textContent =\n                    `${count} ${count === 1 ? \"article\" : \"articles\"}`;\n            }\n\n            if (count > 0) {\n                setStatus(\n                    newsStatus,\n                    `Showing ${count} article${count === 1 ? \"\" : \"s\"} for ${branch}.`\n                );\n            } else {\n                setStatus(\n                    newsStatus,\n                    \"No articles were found right now. Try refreshing in a little while.\"\n                );\n            }\n        } catch (error) {\n            console.error(\"Unable to load engineering news:\", error);\n\n            showEmptyState(\n                newsContainer,\n                \"We couldn't load the news\",\n                \"Please check your connection and try again. If the problem continues, the backend or news source may be unavailable.\"\n            );\n\n            setStatus(\n                newsStatus,\n                error.message || \"Something went wrong while loading news.\",\n                true\n            );\n        } finally {\n            refreshButton.disabled = false;\n\n            const isDashboard = window.location.pathname === \"/\";\n\n            refreshButton.replaceChildren(\n                createElement(\n                    \"span\",\n                    \"\",\n                    \"↻\"\n                ),\n                document.createTextNode(\n                    isDashboard ? \" Refresh news\" : \" Get latest news\"\n                )\n            );\n        }\n    }\n\n    refreshButton.addEventListener(\"click\", () => {\n        loadNews(true);\n    });\n\n    branchSelect.addEventListener(\"change\", () => {\n        loadNews(false);\n    });\n\n    loadNews(false);\n}\n\nfunction renderNews(container, articles) {\n    if (!container) return;\n\n    if (!Array.isArray(articles) || articles.length === 0) {\n        showEmptyState(\n            container,\n            \"No news articles available\",\n            \"There are no matching articles at the moment. Please try again later.\"\n        );\n        return;\n    }\n\n    const fragment = document.createDocumentFragment();\n\n    articles.forEach(article => {\n        fragment.appendChild(createNewsCard(article));\n    });\n\n    container.replaceChildren(fragment);\n}\n\nfunction createNewsCard(article) {\n    const card = createElement(\"article\", \"news-card\");\n\n    const metadata = createElement(\"div\", \"news-card-meta\");\n    metadata.appendChild(\n        createElement(\"span\", \"news-source\", article.source || \"Engineering News\")\n    );\n\n    const published = formatDate(article.published_at);\n\n    metadata.appendChild(\n        createElement(\"span\", \"article-date\", published)\n    );\n\n    const title = createElement(\"h3\");\n    const titleLink = createSafeExternalLink(\n        article.link,\n        article.title || \"Untitled article\"\n    );\n\n    if (titleLink) {\n        title.appendChild(titleLink);\n    } else {\n        title.textContent = article.title || \"Untitled article\";\n    }\n\n    card.append(metadata, title);\n\n    if (article.description) {\n        card.appendChild(\n            createElement(\n                \"p\",\n                \"news-description\",\n                article.description\n            )\n        );\n    }\n\n    if (article.summary) {\n        const summaryBox = createElement(\"div\", \"summary-box\");\n\n        summaryBox.appendChild(\n            createElement(\"div\", \"summary-label\", \"✧ AI Summary\")\n        );\n\n        const summaryList = createElement(\"ul\");\n\n        const bullets = String(article.summary)\n            .split(/\\r?\\n/)\n            .map(line => line.replace(/^\\s*(?:[-*•]+|\\d+[.)])\\s*/, \"\").trim())\n            .filter(Boolean);\n\n        if (bullets.length > 0) {\n            bullets.forEach(bullet => {\n                summaryList.appendChild(\n                    createElement(\"li\", \"\", bullet)\n                );\n            });\n        } else {\n            summaryList.appendChild(\n                createElement(\"li\", \"\", article.summary)\n            );\n        }\n\n        summaryBox.appendChild(summaryList);\n        card.appendChild(summaryBox);\n    }\n\n    const footer = createElement(\"div\", \"news-card-footer\");\n\n    footer.appendChild(\n        createElement(\"span\", \"article-date\", published)\n    );\n\n    const readLink = createSafeExternalLink(\n        article.link,\n        \"Read original article →\",\n        \"article-link\"\n    );\n\n    if (readLink) {\n        footer.appendChild(readLink);\n    }\n\n    card.appendChild(footer);\n\n    return card;\n}\n\n/* =========================================\n   COLLEGE UPDATES\n   ========================================= */\n\nfunction initializeCollegeUpdates() {\n    const collegeContainer = document.getElementById(\"college-container\");\n    const collegeStatus = document.getElementById(\"college-status\");\n    const refreshButton = document.getElementById(\"refresh-college\");\n    const categorySelect = document.getElementById(\"college-category\");\n\n    if (!collegeContainer) {\n        return;\n    }\n\n    let allUpdates = [];\n\n    async function loadCollegeUpdates(forceRefresh = false) {\n        if (refreshButton) {\n            refreshButton.disabled = true;\n            refreshButton.textContent = forceRefresh\n                ? \"Refreshing…\"\n                : \"Loading updates…\";\n        }\n\n        setStatus(collegeStatus, \"Checking for college notices and announcements…\");\n        showLoading(collegeContainer, \"Loading college updates…\");\n\n        const params = new URLSearchParams({\n            limit: \"30\"\n        });\n\n        if (forceRefresh) {\n            params.set(\"refresh\", \"true\");\n        }\n\n        try {\n            const data = await fetchJSON(\n                `${API.college}?${params.toString()}`\n            );\n\n            allUpdates = Array.isArray(data.updates) ? data.updates : [];\n\n            if (data.college_website_configured === false) {\n                showEmptyState(\n                    collegeContainer,\n                    \"Your college portal hasn't been connected yet\",\n                    \"This is expected for now. Once the official college website URL is added to the project settings, available notices and announcements can appear here.\"\n                );\n\n                setStatus(\n                    collegeStatus,\n                    \"College website not configured yet. We'll connect it once you have the official URL.\"\n                );\n\n                return;\n            }\n\n            renderCollegeUpdates(\n                collegeContainer,\n                allUpdates,\n                categorySelect ? categorySelect.value : \"all\"\n            );\n\n            setStatus(\n                collegeStatus,\n                allUpdates.length\n                    ? `Found ${allUpdates.length} college update${allUpdates.length === 1 ? \"\" : \"s\"}.`\n                    : \"No college updates were found. Try refreshing later.\"\n            );\n        } catch (error) {\n            console.error(\"Unable to load college updates:\", error);\n\n            showEmptyState(\n                collegeContainer,\n                \"College updates aren't available\",\n                \"Please try again later. Check that the backend is running and the college website is configured.\"\n            );\n\n            setStatus(\n                collegeStatus,\n                error.message || \"Something went wrong while loading college updates.\",\n                true\n            );\n        } finally {\n            if (refreshButton) {\n                refreshButton.disabled = false;\n\n                refreshButton.replaceChildren(\n                    createElement(\"span\", \"\", \"↻\"),\n                    document.createTextNode(\" Refresh updates\")\n                );\n            }\n        }\n    }\n\n    if (refreshButton) {\n        refreshButton.addEventListener(\"click\", () => {\n            loadCollegeUpdates(true);\n        });\n    }\n\n    if (categorySelect) {\n        categorySelect.addEventListener(\"change\", () => {\n            renderCollegeUpdates(\n                collegeContainer,\n                allUpdates,\n                categorySelect.value\n            );\n        });\n    }\n\n    loadCollegeUpdates(false);\n}\n\nfunction renderCollegeUpdates(container, updates, selectedCategory = \"all\") {\n    if (!container) return;\n\n    const filteredUpdates = selectedCategory === \"all\"\n        ? updates\n        : updates.filter(\n            update => update.category === selectedCategory\n        );\n\n    if (filteredUpdates.length === 0) {\n        showEmptyState(\n            container,\n            \"No updates in this category\",\n            \"Try another category or check again later for new announcements.\"\n        );\n        return;\n    }\n\n    const fragment = document.createDocumentFragment();\n\n    filteredUpdates.forEach(update => {\n        fragment.appendChild(createCollegeUpdateCard(update));\n    });\n\n    container.replaceChildren(fragment);\n}\n\nfunction createCollegeUpdateCard(update) {\n    const card = createElement(\"article\", \"college-update-card\");\n\n    const icon = createElement(\n        \"div\",\n        \"update-icon\",\n        getCollegeCategoryIcon(update.category)\n    );\n\n    icon.setAttribute(\"aria-hidden\", \"true\");\n\n    const content = createElement(\"div\", \"update-content\");\n\n    content.appendChild(\n        createElement(\n            \"h3\",\n            \"\",\n            update.title || \"College update\"\n        )\n    );\n\n    if (update.description) {\n        content.appendChild(\n            createElement(\"p\", \"\", update.description)\n        );\n    }\n\n    const metadata = createElement(\"div\", \"update-meta\");\n\n    metadata.appendChild(\n        createElement(\n            \"span\",\n            \"update-category\",\n            update.category || \"Notice\"\n        )\n    );\n\n    if (update.published_at) {\n        metadata.appendChild(\n            createElement(\n                \"span\",\n                \"\",\n                formatDate(update.published_at)\n            )\n        );\n    }\n\n    content.appendChild(metadata);\n\n    const sourceLink = createSafeExternalLink(\n        update.link,\n        \"View official update →\",\n        \"update-link\"\n    );\n\n    if (sourceLink) {\n        content.appendChild(sourceLink);\n    }\n\n    card.append(icon, content);\n\n    return card;\n}\n\nfunction getCollegeCategoryIcon(category) {\n    const icons = {\n        Examination: \"◷\",\n        Notice: \"▤\",\n        Event: \"✧\",\n        Academic: \"▥\"\n    };\n\n    return icons[category] || \"▤\";\n}\n\n/* ===== THEME SWITCHER ===== */\nfunction initializeTheme() {\n    const root = document.documentElement;\n    const toggle = document.getElementById(\"theme-toggle\");\n    const savedTheme = localStorage.getItem(\"student-ecosystem-theme\");\n    const preferredTheme = window.matchMedia &&\n        window.matchMedia(\"(prefers-color-scheme: dark)\").matches ? \"dark\" : \"light\";\n    const initialTheme = savedTheme || preferredTheme;\n\n    function applyTheme(theme) {\n        root.setAttribute(\"data-theme\", theme);\n        if (toggle) {\n            const dark = theme === \"dark\";\n            toggle.setAttribute(\"aria-pressed\", String(dark));\n            toggle.innerHTML = dark\n                ? '<span aria-hidden=\"true\">☀</span><span>Light mode</span>'\n                : '<span aria-hidden=\"true\">☾</span><span>Dark mode</span>';\n        }\n        localStorage.setItem(\"student-ecosystem-theme\", theme);\n    }\n\n    applyTheme(initialTheme);\n    if (toggle) {\n        toggle.addEventListener(\"click\", () => {\n            applyTheme(root.getAttribute(\"data-theme\") === \"dark\" ? \"light\" : \"dark\");\n        });\n    }\n}\n"
